import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse(`{"title":"What is ApptiveTeams","description":"The employee app that's fully configured through an ApptiveGrid Space.","frontmatter":{"title":"What is ApptiveTeams","description":"The employee app that's fully configured through an ApptiveGrid Space."},"headers":[],"relativePath":"en/apptiveteams/was-ist-apptiveteams.md","filePath":"en/apptiveteams/was-ist-apptiveteams.md","lastUpdated":1787319236000}`),n={name:"en/apptiveteams/was-ist-apptiveteams.md"};function o(r,e,p,h,l,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="what-is-apptiveteams" tabindex="-1">What is ApptiveTeams <a class="header-anchor" href="#what-is-apptiveteams" aria-label="Permalink to &quot;What is ApptiveTeams&quot;">​</a></h1><p><strong>ApptiveTeams</strong> is an employee app for iOS and Android. Employees sign in with their ApptiveGrid account and see the content you maintain in a <strong>Team Space</strong>: forms, links, news, and web content.</p><p>The key point: the app is <strong>configured entirely through ApptiveGrid</strong> — without a single line of code. Change something in the Team Space, and the change shows up in the app right away. No app update through the store is needed for that.</p><h2 id="how-the-configuration-works" tabindex="-1">How the configuration works <a class="header-anchor" href="#how-the-configuration-works" aria-label="Permalink to &quot;How the configuration works&quot;">​</a></h2><p>The app reads specific Grids from your Team Space. What each Grid is used for isn&#39;t decided by its <strong>name</strong>, but by its <strong>Key</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Team Space (Category: apptiveTeams)</span></span>
<span class="line"><span>├── Grid with Key &quot;config&quot;    → the app&#39;s logo and color</span></span>
<span class="line"><span>├── Grid with Key &quot;tabs&quot;      → the tabs in the navigation bar</span></span>
<span class="line"><span>└── Grid with Key &quot;settings&quot;  → custom entries on the settings screen</span></span></code></pre></div><p>The same applies to the fields within these Grids. You&#39;re free to name them however you like — only the Keys matter.</p><p>→ <a href="/en/apptiveteams/team-space">Set up the Team Space</a></p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An <strong>ApptiveGrid account</strong> for your organization and for everyone who will use the app.</li><li>A <strong>Space with the category <code>apptiveTeams</code></strong>. The app only offers Spaces with this category for selection.</li><li>All employees invited as <strong>Members</strong> of this Space. → <a href="/en/zusammenarbeit/personen-einladen">Invite people</a></li><li>The <strong>ApptiveTeams app</strong> from the App Store (iOS) or Google Play (Android).</li></ul><div class="tip custom-block"><p class="custom-block-title">Start with a template</p><p>Building a Team Space from scratch means creating every Grid, Key, and field yourself. To get started faster, there&#39;s a ready-made Team Space template — reach out to us and we&#39;ll set it up together with you.</p></div><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li><strong>Install the app</strong> — download ApptiveTeams from the App Store or Google Play.</li><li><strong>Sign in</strong> — with your ApptiveGrid account. Signing in opens the ApptiveGrid login in the browser.</li><li><strong>Choose a team</strong> — the app shows all Team Spaces you&#39;re a member of. If there&#39;s exactly one, it opens automatically.</li><li><strong>Get started</strong> — the app loads branding, tabs, and content from the Team Space.</li></ol><div class="tip custom-block"><p class="custom-block-title">See changes immediately</p><p>The <strong>refresh icon</strong> in the top right reloads the configuration in the app. You&#39;ll need this constantly while setting things up — after every change in the Team Space.</p></div><p>You can switch between multiple Team Spaces at any time via <strong>Switch team</strong> on the settings screen.</p><h2 id="what-you-can-build-with-it" tabindex="-1">What you can build with it <a class="header-anchor" href="#what-you-can-build-with-it" aria-label="Permalink to &quot;What you can build with it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use case</th><th>Implementation</th></tr></thead><tbody><tr><td>Quick access to forms</td><td>Tile tab with links to ApptiveGrid forms</td></tr><tr><td>Bulletin board, news</td><td>Card tab with image, text, and action button</td></tr><tr><td>Intranet, shift schedule</td><td>WebView tab with the relevant address</td></tr><tr><td>Sick leave, vacation request</td><td>Form tile that opens directly inside the app</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/team-space">Set up the Team Space</a></li><li><a href="/en/apptiveteams/tabs">Set up tabs</a></li><li><a href="/en/apptiveteams/kacheln-und-karten">Tiles and cards</a></li></ul>`,19)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
